param([Parameter(Mandatory=$true)][string]$InstallRoot,[Parameter(Mandatory=$true)][string]$DataRoot,[switch]$Quiet)
$ErrorActionPreference='Stop';try{$sec=Get-Content (Join-Path $DataRoot 'host-security.json') -Raw|ConvertFrom-Json;if(-not[bool]$sec.root_attested){throw'ROOT_NOT_ATTESTED'};$root=Get-Content (Join-Path $DataRoot 'root\root.json') -Raw|ConvertFrom-Json;$cert=Get-Item ('Cert:\LocalMachine\My\'+$root.thumbprint);$bytes=[IO.File]::ReadAllBytes((Join-Path $InstallRoot 'payload.sha256'));$sig=[Convert]::FromBase64String((Get-Content (Join-Path $DataRoot 'root\payload.sig') -Raw).Trim());$pub=[Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPublicKey($cert);if(-not$pub.VerifyData($bytes,$sig,[Security.Cryptography.HashAlgorithmName]::SHA256,[Security.Cryptography.RSASignaturePadding]::Pkcs1)){throw'ROOT_SIGNATURE_INVALID'};foreach($line in Get-Content (Join-Path $InstallRoot 'payload.sha256')){if([string]::IsNullOrWhiteSpace($line)){continue};$exp=$line.Substring(0,64);$rel=$line.Substring(66).Replace('/','\');$p=Join-Path $InstallRoot $rel;if(-not(Test-Path $p)){throw"PAYLOAD_MISSING:$rel"};if((Get-FileHash $p -Algorithm SHA256).Hash.ToLowerInvariant()-ne$exp.ToLowerInvariant()){throw"PAYLOAD_HASH:$rel"}};if(-not$Quiet){'ROOT_VERIFY=PASS'};exit 0}catch{if(-not$Quiet){"ROOT_VERIFY=FAIL $($_.Exception.Message)"};exit 11}
